import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchApplications,
  cancelApplication,
} from "../Features/ApplicationSlice";
import "../Styles/MyApplications.css";

const MyApplications = () => {
  const dispatch = useDispatch();
  // Logout function to clear user session and navigate to login
  const handleLogout = async () => {
    // Remove all saved session data
    localStorage.removeItem("role");
    localStorage.removeItem("loggedUser");
    localStorage.removeItem("token"); // optional if you used token
    localStorage.removeItem("applications");

    // Also reset Redux state
    dispatch(logout());

    // Small delay before navigation
    await new Promise((resolve) => setTimeout(resolve, 100));
    navigate("/login");
  };

  const { applications, isLoading } = useSelector(
    (state) => state.applications
  );

  // Load user's applications when the page opens
  useEffect(() => {
    const loggedUser = JSON.parse(localStorage.getItem("loggedUser"));
    if (loggedUser?.email) {
      dispatch(fetchApplications(loggedUser.email));
    }
  }, [dispatch]);

  // Cancel an application
  const handleCancel = (id) => {
    dispatch(cancelApplication(id))
      .unwrap()
      .then(() => alert("Application canceled successfully."))
      .catch(() => alert("Error canceling application."));
  };

  if (isLoading) return <p>Loading applications...</p>;

  return (
    <div className="applications-page">
      <h1 className="applications-title">
        My <span className="accent">Applications</span>
      </h1>
      <p className="applications-sub">
        Track the status of your submitted job applications.
      </p>

      <div className="applications-list">
        {applications.length === 0 ? (
          <p>No applications yet.</p>
        ) : (
          applications.map((app) => (
            <div className="application-card" key={app._id}>
              <div className="app-info">
                <div className="app-icon">🏢</div>
                <div>
                  <h3 className="job-title">{app.jobTitle}</h3>
                  <p className="company">Company: {app.organization}</p>
                  <p className="details">Email: {app.applicantEmail}</p>
                  <p className="status">
                    Status: {app.status || "Pending Review"}
                  </p>
                </div>
              </div>

              <div className="app-actions">
                <button
                  className="withdraw-btn"
                  onClick={() => handleCancel(app._id)}
                >
                  Cancel
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default MyApplications;
